import { Button, Dialog, DialogActions, DialogContent, DialogTitle, TextField } from "@mui/material"
import { PropsWithChildren, useState } from "react"
import { useTranslation } from "react-i18next"
interface IEditableTextProps {
    setText: (text: string) => void
    title?: string
    cancelText?: string
    saveText?: string
    contentText?: string
    helperText?: string
    minHeight?: string
    multiline?:boolean
}
import React from 'react'
export function EditableText({ setText, title, cancelText, saveText, contentText, helperText, minHeight, children, multiline }: IEditableTextProps & PropsWithChildren) {
    const { t } = useTranslation('fanfanlo/mui/dialog/content')
    const [editText, setEditText] = useState('')
    const [isEditing, setIsEditing] = useState(false)
    function handleEdit(s: string) {
        setEditText(s)
    }
    function onConfirmClick(){
        setIsEditing(false); 
        setText(editText) 
    }

    function onCancel(){
        setIsEditing(false)
    }
    function onKeyDown(e:any){
        if (e.key === 'Enter' && !multiline) {
            onConfirmClick();
        }
    }
    return (
        <>
            <span data-testid="EditableText__triggerSpan__01JFXYZAH7H8I9J0K1L2M3N4" style={{cursor: 'pointer', width: '100%', textAlign: 'center', display:"inline-block", backgroundColor: '', minHeight:minHeight || '1rem'}} onClick={() => setIsEditing(true)}><span >{children || ''}</span></span>
            {isEditing && (
                <Dialog open={isEditing} onClose={() => setIsEditing(false)}>
                    <DialogTitle>{title ||t('EditableText.title')}</DialogTitle>
                    {contentText && <DialogContent>{contentText}</DialogContent>}
                    <DialogContent>
                        <TextField
                        onKeyDown={(e)=>{onKeyDown(e)}}
                        multiline={multiline}
                        data-testid="EditableText__textField__01JFXYZAI8I9J0K1L2M3N4O5"
                        id="editable-text"
                        aria-label="editable-text"
                            autoFocus
                            required
                            fullWidth
                            helperText={helperText}
                            variant="standard"
                            value={editText} onChange={(e) => handleEdit(e.target.value)} />

                    </DialogContent>
                    <DialogActions>
                        <Button
                        data-testid="EditableText__cancelButton__01JFXYZAJ9J0K1L2M3N4O5P6"
                        id="editable-text-cancel"
                        data-id="editable-text-cancel"
                        onClick={onCancel}>{cancelText || t('EditableText.cancel')}</Button>
                        <Button
                        data-testid="EditableText__saveButton__01JFXYZAK0K1L2M3N4O5P6Q7"
                        id="editable-text-save"
                        data-id="editable-text-save"
                        onClick={onConfirmClick}>{saveText || t('EditableText.save')}</Button>
                    </DialogActions>
                </Dialog>
            )}
        </>
    )
}

